  Definition CInv (i : Z) (Mi : word -> option byte) : Prop :=
    (forall x : word,
        ~ (arr <= bv_unsigned x < arr + 4 * i)%Z -> ~ (cmap + 16 <= bv_unsigned x < cmap + 20)%Z ->
        Mi x = M x)
    /\ mem_grows M Mi
    /\ rdn SEGS Mi (Z_to_bv 64 (cmap + 16)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 i)).

